import { LightningElement, api } from 'lwc';

const THEME_CLASSES = {
    New: 'slds-theme_info',
    Escalated: 'slds-theme_error',
    Closed: 'slds-theme_success'
};

export default class CaseStatusBadge extends LightningElement {
    @api status;

    get hasStatus() {
        return this.status !== undefined && this.status !== null && this.status !== '';
    }

    get badgeClass() {
        const themeClass = THEME_CLASSES[this.status];
        return themeClass ? `slds-badge ${themeClass}` : 'slds-badge';
    }
}
