public with sharing class HouseholdService {

    /**
     * Creates a single new NPSP Household Account and inserts all given Contacts
     * into it. The first Contact in the list becomes the household's primary
     * contact. The Account's name, greetings, etc. are fully managed by NPSP.
     *
     * @param members new Contacts (no Id, no AccountId) to place in one household
     * @return the Id of the newly created NPSP Household Account
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('HouseholdService.createHousehold requires at least one contact.');
        }

        // Work on clones so we never mutate the caller's records.
        Contact primary = members[0].clone(false, false);
        primary.Id = null;
        primary.AccountId = null;

        // Let NPSP's triggers auto-create the Household Account for this contact.
        // NPSP picks the Household Account record type, applies its naming rules,
        // generates greetings and marks this contact as npsp__Primary_Contact__c.
        insert primary;

        // Trigger-created AccountId is not reflected on our in-memory record,
        // so read it back.
        primary = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primary.Id
            LIMIT 1
        ];

        Id householdId = primary.AccountId;
        if (householdId == null) {
            throw new IllegalStateException('NPSP did not create a household for the primary contact.');
        }

        if (members.size() > 1) {
            List<Contact> familyMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact member = members[i].clone(false, false);
                member.Id = null;
                // Attach to the same household; NPSP will refresh the household
                // name and greetings to account for all family members.
                member.AccountId = householdId;
                familyMembers.add(member);
            }
            insert familyMembers;
        }

        return householdId;
    }
}
