public inherited sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS_LIMIT = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // 1. maxRows
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS_LIMIT) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // 2. fields
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // 3. object
        Schema.SObjectType sobjType = objectApiName == null ? null : Schema.getGlobalDescribe().get(objectApiName);
        if (sobjType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        Schema.DescribeSObjectResult objDesc = sobjType.getDescribe();
        if (!objDesc.isAccessible()) {
            throw new SearchException('Running user does not have read access to object ' + objDesc.getName());
        }

        Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();

        // 4. resolve + validate select fields
        Set<String> seen = new Set<String>();
        List<String> selectFields = new List<String>{ 'Id' };
        for (String f : fields) {
            if (String.isBlank(f)) throw new SearchException('Field name must not be blank.');
            Schema.SObjectField token = fieldMap.get(f);
            if (token == null) {
                throw new SearchException('Field is not a field of ' + objDesc.getName() + ': ' + f);
            }
            Schema.DescribeFieldResult fd = token.getDescribe();
            if (!fd.isAccessible()) {
                throw new SearchException('No read (FLS) access to field: ' + fd.getName());
            }
            String canonical = fd.getName().toLowerCase();
            if (canonical != 'id' && !seen.contains(canonical)) {
                seen.add(canonical);
                selectFields.add(fd.getName());
            }
        }

        // 5. filters
        List<String> conditions = new List<String>();
        if (filters != null) {
            for (String key : filters.keySet()) {
                if (String.isBlank(key)) throw new SearchException('Filter field name must not be blank.');
                Schema.SObjectField token = fieldMap.get(key);
                if (token == null) {
                    throw new SearchException('Filter field is not a field of ' + objDesc.getName() + ': ' + key);
                }
                Schema.DescribeFieldResult fd = token.getDescribe();
                if (!fd.isFilterable()) throw new SearchException('Field cannot be used in filters: ' + fd.getName());
                if (!fd.isAccessible()) throw new SearchException('No read (FLS) access to filter field: ' + fd.getName());
                conditions.add(fd.getName() + ' = ' + toSoqlLiteral(filters.get(key)));
            }
