/**
 * @description GiftImportService routes one-off website gifts through NPSP's Data
 * Importer (BDI) instead of inserting Contacts and Opportunities directly.
 *
 * Design:
 *   1. Each gift is staged as an npsp.Data_Import__c record. These staged records
 *      remain in the org and serve as the audit trail of what was imported.
 *   2. The staged records are processed synchronously, in the same transaction,
 *      via NPSP's DataImportService Apex API. NPSP therefore applies the org's
 *      Data Import settings: contacts are matched on first name, last name and
 *      email (creating the contact and household when no match exists) and
 *      existing donations are never matched, so one donation is created per gift.
 *   3. Results are returned one per gift, in input order. A row that NPSP rejects
 *      does not stop the other rows; its failure information from NPSP is carried
 *      back in ImportResult.errorMessage.
 *
 * Bulk safety: staging uses a single DML statement regardless of call size, and a
 * single DataImportService.run() call processes the whole batch (e.g. 200 gifts).
 */
public with sharing class GiftImportService {

    /**
     * @description A single gift received from the website.
     */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /**
     * @description Outcome of importing one gift, in the order of the input.
     */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * @description Imports website gifts through NPSP's Data Importer.
     * @param gifts The gifts to import. A null or empty list returns an empty list.
     * @return One ImportResult per gift, in input order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        // Null or empty input: nothing to do.
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // ------------------------------------------------------------------
        // 1. Stage one NPSP Data Import record per gift (single DML, bulk-safe).
        //    These records persist in the org as the audit trail of the import.
        // ------------------------------------------------------------------
        List<npsp.Data_Import__c> dataImports = new List<npsp.Data_Import__c>();
        for (WebGift gift : gifts) {
            dataImports.add(new npsp.Data_Import__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c  = gift.lastName,
                npsp__Contact1_Email__c     = gift.email,
                npsp__Donation_Amount__c    = gift.amount,
                npsp__Donation_Date__c      = gift.giftDate
            ));
        }
        insert dataImports;

        // ------------------------------------------------------------------
        // 2. Process the staged records synchronously, in this transaction,
        //    using NPSP's Data Import Apex API. No settings are overridden, so
        //    the org's Data Import settings govern contact matching and
        //    donation matching behaviour.
        // ------------------------------------------------------------------
        List<npsp.DataImportService.DataImportResult> runResults;
        try {
            runResults = npsp.DataImportService.run(dataImports);
        } catch (Exception ex) {
            // NPSP failed before it could produce per-row results. Do not let
            // this abort the caller's transaction: report every gift as failed
            // and carry NPSP's failure information back. The staged Data Import
            // records remain in the org as the audit trail.
            for (Integer i = 0; i < dataImports.size(); i++) {
                results.add(buildFailure(ex.getMessage()));
            }
            return results;
        }

        // ------------------------------------------------------------------
        // 3. Build one ImportResult per gift, in input order, from the
        //    processed Data Import records. The imported (matched or created)
        //    record Ids are written back onto each Data Import record by NPSP.
        // ------------------------------------------------------------------
        for (Integer i = 0; i < runResults.size() && i < gifts.size(); i++) {
            npsp.DataImportService.DataImportResult runResult = runResults[i];
            ImportResult result = new ImportResult();

            result.success = (runResult != null && runResult.success == true);

            if (result.success && runResult.dataImport != null) {
                // The contact NPSP matched or created, and the donation it created.
                result.contactId     = runResult.dataImport.npsp__Contact1_Imported_Id__c;
                result.opportunityId = runResult.dataImport.npsp__Donation_Imported_Id__c;
            } else if (!result.success) {
                // Row rejected by NPSP: surface NPSP's failure information, but
                // the other rows continue to be processed.
                String message = 'NPSP Data Import failed for this gift.';
                if (runResult != null && runResult.errors != null && !runResult.errors.isEmpty()) {
                    message = String.join(runResult.errors, '; ');
                }
                result.errorMessage = message;
            }

            results.add(result);
        }

        // Defensive: if NPSP returned fewer results than staged rows (not
        // expected), report the remainder as failed rather than silently
        // dropping gifts from the response.
        while (results.size() < gifts.size()) {
            results.add(buildFailure('NPSP Data Import did not return a result for this gift.'));
        }

        return results;
    }

    /**
     * @description Builds a failed ImportResult with NPSP's failure information.
     * @param message The failure information reported by NPSP (or the platform).
     * @return An ImportResult with success = false.
     */
    private static ImportResult buildFailure(String message) {
        ImportResult result = new ImportResult();
        result.success = false;
        result.errorMessage = message;
        return result;
    }
}
```

